<div class="grid"><form id="tool" class="panel"><label>Customer price</label><input name="revenue" type="number" min="0" step="0.01" required><label>Materials</label><input name="materials" type="number" min="0" step="0.01" required><label>Labor</label><input name="labor" type="number" min="0" step="0.01" required><label>Other costs</label><input name="other" type="number" min="0" step="0.01" value="0" required><button>Check this job</button><p id="error" class="error"></p></form><section id="result" class="stat hidden"><span>Estimated profit</span><b id="profit"></b><p><strong id="margin"></strong> margin</p><p id="breakdown"></p><p id="usage"></p></section></div>
<script>
const form=document.querySelector('#tool');let attempt=crypto.randomUUID();form.addEventListener('submit',async event=>{event.preventDefault();const button=form.querySelector('button');button.disabled=true;document.querySelector('#error').textContent='';const session=await fetch('/api/session.php').then(r=>r.json());const fields=Object.fromEntries(new FormData(form));const response=await fetch('/api/tools/profit-peek.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...fields,csrf:session.csrf,idempotencyKey:attempt})});const data=await response.json();button.disabled=false;if(!response.ok){document.querySelector('#error').textContent=data.error;return}attempt=crypto.randomUUID();const money=new Intl.NumberFormat(undefined,{style:'currency',currency:'USD'});document.querySelector('#profit').textContent=money.format(data.result.profit);document.querySelector('#margin').textContent=data.result.margin+'%';document.querySelector('#breakdown').textContent=money.format(data.result.revenue)+' revenue minus '+money.format(data.result.cost)+' costs.';document.querySelector('#usage').textContent=data.usage.remaining+' actions remaining this month.';document.querySelector('#result').classList.remove('hidden')});
</script><?php endif; ?></main></body></html>
